fn prog(entry: &str, mods: &[(&str, &str)]) -> Checked {
    let mut l = MapLoader::default();
    for (n, s) in mods { l.0.insert((*n).into(), (*s).into()); }
    check_program("main", entry, &mut l, &hosts())
}

